 "content": "from collections import deque

def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen
                            and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            out.append((color, cells))
    return out

def _shape(cells):
    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    return frozenset((r - min_r, c - min_c) for r, c in cells)

def transform(grid):
    objects = _components(grid)
    templates = {}
    for color, cells in objects:
        if color != 1:
            templates.setdefault(_shape(cells), set()).add(color)
    result = [row[:] for row in grid]
    for color, cells in objects:
        if color == 1:
            matches = templates.get(_shape(cells), set())
            if len(matches) == 1:
                new_color = next(iter(matches))
                for r, c in cells:
                    result[r][c] = new_color
    return result
